// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address originalOwner = c.smartfix_owner();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        require(!success, "Call succeeded unexpectedly");
        assertTrue(c.smartfix_owner() == originalOwner);
    }
}
